'use client';

import { useRef, useState } from 'react';
import { services } from './services';

const clinicNumber = '923203771995';
const options = [...services, { slug: 'help-me-choose', title: 'Not sure? Help me choose' }];
const symbols = ['✧', '✦', '⌁', '✧', '+', '♧', '+', '◇', '?'];

export default function BookingWidget() {
  const dialog = useRef(null);
  const heading = useRef(null);
  const trigger = useRef(null);
  const [step, setStep] = useState(1);
  const [service, setService] = useState('');
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [name, setName] = useState('');
  const [mobile, setMobile] = useState('');
  const [error, setError] = useState('');
  const [prepared, setPrepared] = useState(false);
  const [today, setToday] = useState('');
  const [copyStatus, setCopyStatus] = useState('');
  const messageField = useRef(null);

  function open() {
    const now = new Date();
    setToday(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`);
    setError('');
    dialog.current?.showModal();
    heading.current?.focus();
  }

  function move(next) {
    setError('');
    setPrepared(false);
    setCopyStatus('');
    setStep(next);
    requestAnimationFrame(() => heading.current?.focus());
  }

  const formattedDate = date ? new Date(`${date}T12:00:00`).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'long', year: 'numeric' }) : '';
  const message = `Hello Family Dental Clinic! I would like to request an appointment.\n\nName: ${name.trim()}\nMobile: ${mobile.trim()}\nService: ${service}\nPreferred date: ${formattedDate}\nPreferred time: ${time}\n\nPlease confirm availability and the consultation fee. Thank you!`;
  const whatsappURL = `https://wa.me/${clinicNumber}?text=${encodeURIComponent(message)}`;

  function next(event) {
    event.preventDefault();
    if (step === 1 && !service) { setError('Please choose a service, or select “Help me choose”.'); return; }
    if (step === 2 && (!date || date < today || !time)) { setError('Please choose today or a future date and your preferred time.'); return; }
    if (step < 3) { move(step + 1); return; }
    if (!name.trim()) { setError('Please enter your name.'); return; }
    if (!/^[+\d\s().-]+$/.test(mobile) || mobile.replace(/\D/g, '').length < 10 || mobile.replace(/\D/g, '').length > 15) { setError('Please enter a valid mobile number, for example 0320 3771995.'); return; }
    setError('');
    setPrepared(true);
    // The visitor reviews and sends the message in WhatsApp.
    window.open(whatsappURL, '_blank', 'noopener,noreferrer');
  }

  async function copyMessage() {
    try { await navigator.clipboard.writeText(message); setCopyStatus('Appointment request copied.'); }
    catch { messageField.current?.focus(); messageField.current?.select(); setCopyStatus('Select and copy your message below.'); }
  }

  return <>
    <button ref={trigger} type="button" className="booking-launcher" onClick={open}><span className="booking-launcher-icon" aria-hidden="true">▦</span><span>Book a Visit<small>Your smile starts here</small></span><span aria-hidden="true">↗</span></button>
    <dialog ref={dialog} className="booking-dialog" aria-labelledby="booking-title" onClose={() => trigger.current?.focus()} onClick={event => { if (event.target === event.currentTarget) { const rect = event.currentTarget.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) dialog.current?.close(); } }}>
      <div className="booking-layout">
        <aside className="booking-welcome">
          <span className="booking-clinic">FAMILY DENTAL · MIRPUR</span>
          <span className="booking-welcome-art" aria-hidden="true">✧</span>
          <h2>A little care.<br />A brighter<br /><em>beginning.</em></h2>
          <p>Let’s find a time for your smile. Share a few details and start a conversation with our clinic.</p>
          <div className="booking-reassurance"><span>✓ &nbsp; No account needed</span><span>✓ &nbsp; Just three simple steps</span><span>✓ &nbsp; Confirm directly with the clinic</span></div>
          <a href="tel:+923203771995">Prefer to call? <strong>+92 320 3771995 ↗</strong></a>
        </aside>
        <div className="booking-main">
          <button className="booking-close" type="button" aria-label="Close booking" onClick={() => dialog.current?.close()}>×</button>
          <div className="booking-step-label">LET’S PLAN YOUR VISIT <span>Step {step} of 3</span></div>
          <ol className="booking-progress" aria-label="Booking progress">{['Your care', 'Your time', 'Your details'].map((label, i) => <li key={label} className={step >= i + 1 ? 'is-active' : ''} aria-current={step === i + 1 ? 'step' : undefined}><span>{step > i + 1 ? '✓' : i + 1}</span>{label}</li>)}</ol>
          <h2 id="booking-title" ref={heading} tabIndex={-1}>{step === 1 ? 'What brings you in?' : step === 2 ? 'When suits you best?' : 'Let’s make the introduction.'}</h2>
          <p className="booking-subtitle">{step === 1 ? 'Choose a service. It’s okay if you’re not sure yet.' : step === 2 ? 'Choose your preference. The clinic will confirm availability.' : 'Your request will open in WhatsApp for you to review and send.'}</p>
          <form onSubmit={next}>
            {step === 1 && <fieldset className="booking-options"><legend className="booking-sr-only">Choose your dental service</legend>{options.map((option, i) => <label key={option.slug} className={`booking-option ${service === option.title ? 'is-selected' : ''}`}><input type="radio" name="booking-service" value={option.title} checked={service === option.title} onChange={() => { setService(option.title); setError(''); }} /><span className="booking-option-symbol" aria-hidden="true">{symbols[i]}</span><span>{option.title}</span><span className="booking-option-check" aria-hidden="true">{service === option.title ? '✓' : ''}</span></label>)}</fieldset>}
            {step === 2 && <div className="booking-schedule"><label className="booking-field">Preferred date<input type="date" value={date} min={today} required onChange={e => { setDate(e.target.value); setError(''); }} /></label><fieldset className="booking-times"><legend>Preferred time of day</legend>{[['Morning', 'Start your day with a smile', '☀'], ['Afternoon', 'A little time for yourself', '◷'], ['Evening', 'Find a moment after your day', '☾']].map(([label, text, icon]) => <label key={label} className={time === label ? 'is-selected' : ''}><input type="radio" name="booking-time" value={label} checked={time === label} onChange={() => { setTime(label); setError(''); }} /><span aria-hidden="true">{icon}</span><span><strong>{label}</strong><small>{text}</small></span><span className="booking-option-check" aria-hidden="true">{time === label ? '✓' : ''}</span></label>)}</fieldset><p className="booking-info">These are preferences, not live appointment slots. Opening hours and your final appointment time will be confirmed by the clinic.</p></div>}
            {step === 3 && <div className="booking-details"><div className="booking-summary"><span>YOUR VISIT AT A GLANCE</span><strong>{service}</strong><p>{formattedDate} · {time}</p><button type="button" onClick={() => move(1)}>Edit preferences ↗</button></div><label className="booking-field">Your name<input name="name" autoComplete="name" placeholder="Enter your name" value={name} maxLength={80} required onChange={e => { setName(e.target.value); setPrepared(false); setError(''); setCopyStatus(''); }} /></label><label className="booking-field">Mobile number<input name="tel" type="tel" autoComplete="tel" inputMode="tel" placeholder="e.g. 0320 3771995" value={mobile} maxLength={24} required onChange={e => { setMobile(e.target.value); setPrepared(false); setError(''); setCopyStatus(''); }} /></label><p className="booking-info">Your details are included in the WhatsApp message. You choose when to send it. Your appointment is confirmed only after the clinic replies.</p></div>}
            {error && <p className="booking-error" role="alert">{error}</p>}
            <div className="booking-actions">{step > 1 && <button type="button" className="booking-back" onClick={() => move(step - 1)}>← Back</button>}<button type="submit" className="booking-next">{step === 3 ? 'Continue to WhatsApp' : 'Continue'} <span aria-hidden="true">↗</span></button></div>
            {prepared && step === 3 && <div className="booking-ready"><p role="status"><strong>Your message is ready.</strong> Send it in WhatsApp, then wait for the clinic to confirm your visit.</p><a href={whatsappURL} target="_blank" rel="noreferrer">Open WhatsApp again ↗</a><details><summary>Prefer to copy your request?</summary><textarea ref={messageField} aria-label="Your appointment request" value={message} readOnly rows={7} /><button type="button" onClick={copyMessage}>Copy message</button><p role="status">{copyStatus}</p></details></div>}
          </form>
          <p className="booking-bottom-note">No payment required to send an enquiry.</p>
        </div>
      </div>
    </dialog>
  </>;
}
